#region References

using Microsoft.VisualStudio.TestTools.UnitTesting;

#endregion

namespace Cornerstone.Generators.UnitTests.Cornerstone;

[TestClass]
public class DirectPropertyTests : GeneratorUnitTest
{
	#region Methods

	[TestMethod]
	public void DirectGetAndSet()
	{
		var input = """
					public partial class Test : Control
					{
						[DirectProperty]
						public partial int Bar { get; set; }
					}
					""";

		// Generated Code - Expected
		var expected = new[]
		{
			"""
			using System;
			using System.Collections.Generic;
			// <auto-generated>
			// Auto-generated by Cornerstone.Generators
			// </auto-generated>
			partial class Test
			{
				private global::System.Int32 _bar;
				public static readonly global::Cornerstone.Presentation.DirectProperty<global::Test, global::System.Int32> BarProperty = global::Cornerstone.Presentation.PresentationProperty.RegisterDirect<global::Test, global::System.Int32>(nameof(Bar), getter: x => x._bar, setter: (x, v) => x.Bar = v);
				public partial global::System.Int32 Bar
				{
					get => _bar;
					set => SetAndRaise(BarProperty, ref _bar, value);
				}
			}
			""",
			"""
			// <auto-generated>
			// Auto-generated by Cornerstone.Generators
			// </auto-generated>
			namespace TestCompilation
			{
				public static partial class CornerstoneGenerated
				{
					[global::System.Runtime.CompilerServices.ModuleInitializer]
					public static void Initialize()
					{
					}
				}
			}
			"""
		};
		// Generated Code - /Expected

		ValidateSource(input, expected);
	}

