	[TestMethod]
	public void DirectForwardToViewModel()
	{
		var input = """
					public partial class Test : TemplatedControl<TestViewModel>
					{
						[DirectProperty(nameof(TestViewModel.Bar))]
						public partial int Bar { get; set; }
					}

					public class TestViewModel
					{
						public int Bar { get; set; }
					}
					""";

		// Generated Code - Expected
		var expected = new[]
		{
			"""
			using System;
			using System.Collections.Generic;
			// <auto-generated>
			// Auto-generated by Cornerstone.Generators
			// </auto-generated>
			partial class Test
			{
				private global::System.Int32 _barNotified;
				public static readonly global::Cornerstone.Presentation.DirectProperty<global::Test, global::System.Int32> BarProperty = global::Cornerstone.Presentation.PresentationProperty.RegisterDirect<global::Test, global::System.Int32>(nameof(Bar), getter: x => x.ViewModel.Bar, setter: (x, v) => x.Bar = v);
				public partial global::System.Int32 Bar
				{
					get => ViewModel.Bar;
					set
					{
						var old = ViewModel.Bar;
						if (global::System.Collections.Generic.EqualityComparer<global::System.Int32>.Default.Equals(old, value))
						{
							return;
						}
						ViewModel.Bar = value;
						RaisePropertyChanged(BarProperty, old, value);
						_barNotified = value;
					}
				}
				private void SyncForwardedViewModelProperties(string propertyName)
				{
					switch (propertyName)
					{
						case null:
						{
							SyncForwardedBar();
							break;
						}
						case "Bar":
						{
							SyncForwardedBar();
							break;
						}
					}
				}
				private void SyncForwardedBar()
				{
					var vm = ViewModel;
					if (vm == null)
					{
						return;
					}
					var value = vm.Bar;
					if (global::System.Collections.Generic.EqualityComparer<global::System.Int32>.Default.Equals(_barNotified, value))
					{
						return;
					}
					RaisePropertyChanged(BarProperty, _barNotified, value);
					_barNotified = value;
				}
			}
			""",
			"""
			// <auto-generated>
			// Auto-generated by Cornerstone.Generators
			// </auto-generated>
			namespace TestCompilation
			{
				public static partial class CornerstoneGenerated
				{
					[global::System.Runtime.CompilerServices.ModuleInitializer]
					public static void Initialize()
					{
					}
				}
			}
			"""
		};
		// Generated Code - /Expected

		ValidateSource(input, expected);
	}

